<?php $title='Pengaturan';require '_head.php';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$logo=upload_or_keep('logo','logo',setting('logo'));foreach(['site_name','description','about_title','about','address','phone','whatsapp','email','instagram','facebook','tiktok'] as $k)$pdo->prepare('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute([$k,$_POST[$k]??'']);$pdo->prepare('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute(['logo',$logo]);$saved=true;}catch(Throwable $e){$msg=$e->getMessage();}}
?><h1>Pengaturan</h1><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><div class="panel"><form method="post" enctype="multipart/form-data"><label>Logo saat ini</label><?php if(setting('logo')):?><p><img class="logo-preview" src="<?=e(setting('logo'))?>" alt="Logo"></p><?php else:?><p>Belum ada logo custom.</p><?php endif;?><label class="upload-label">Upload logo<input type="file" name="logo" accept="image/jpeg,image/png,image/webp" ><small>JPG, PNG, WebP • maksimal 5 MB. Kosongkan jika tidak ingin mengganti.</small></label><?php foreach(['site_name'=>'Nama website','description'=>'Deskripsi singkat','about_title'=>'Judul tentang','about'=>'Tentang kami','address'=>'Alamat','phone'=>'Telepon','whatsapp'=>'WhatsApp (angka saja)','email'=>'Email','instagram'=>'Instagram'] as $k=>$label):?><label><?=e($label)?></label><?php if(in_array($k,['about','description'])):?><textarea name="<?=$k?>"><?=e(setting($k))?></textarea><?php else:?><input name="<?=$k?>" value="<?=e(setting($k))?>"><?php endif;endforeach;?><button>Simpan Pengaturan</button></form></div><?php require '_foot.php';?>